from dataclasses import dataclass

from shop.domain.ports import Mailer, OrderRepository


@dataclass
class Order:
    id: str
    total_cents: int


def place(order: Order, repo: OrderRepository) -> None:
    repo.save(order)


def notify_placed(order: Order, to_address: str, mailer: Mailer) -> None:
    mailer.send(
        to_address=to_address,
        subject=f"Order {order.id} placed",
        body=f"Your order {order.id} has been placed.",
    )

from typing import TYPE_CHECKING, Protocol

if TYPE_CHECKING:
    from shop.domain.order import Order


class OrderRepository(Protocol):
    def save(self, order: "Order") -> None: ...


class Mailer(Protocol):
    def send(self, to_address: str, subject: str, body: str) -> None: ...

